function detectMimeFromName(fileName, fallback) {
  const name = String(fileName || '').toLowerCase();
  if (name.endsWith('.pdf')) return 'application/pdf';
  if (name.endsWith('.png')) return 'image/png';
  if (name.endsWith('.jpg') || name.endsWith('.jpeg')) return 'image/jpeg';
  if (name.endsWith('.heic')) return 'image/heic';
  if (name.endsWith('.webp')) return 'image/webp';
  return fallback || '';
}

function getHeader(name) {
  const h = $input.item.json.headers || {};
  return h[name] || h[name.toLowerCase()] || '';
}

const rawMessageId = getHeader('message-id') || $input.item.json.id || '';
const messageId = rawMessageId.replace(/^message-id:\s*/i, '').trim();
const gmailId = $input.item.json.id || '';

const dateHeader = getHeader('date') || $input.item.json.date || '';
let dateEmail = '';
if (dateHeader) {
  const d = new Date(dateHeader);
  if (!isNaN(d.getTime())) dateEmail = d.toISOString().slice(0, 10);
}

const fromHeader = getHeader('from') || $input.item.json.from || '';
const fromMatch = fromHeader.match(/<([^>]+)>/) || fromHeader.match(/([^\s]+@[^\s]+)/);
const fromAddress = (fromMatch ? (fromMatch[1] || fromMatch[0]) : fromHeader).trim();
const subject = getHeader('subject') || $input.item.json.subject || '';
const bodyText = String($input.item.json.text || $input.item.json.snippet || '').slice(0, 12000);

const binary = $input.item.binary || {};
const documentItems = [];

for (const [key, binaryData] of Object.entries(binary)) {
  if (!binaryData) continue;
  const fileName = binaryData.fileName || key;
  const mimeType = detectMimeFromName(fileName, binaryData.mimeType || '');
  if (mimeType !== 'application/pdf' && !mimeType.startsWith('image/')) continue;

  documentItems.push({
    key,
    fileName,
    mimeType,
    fileSize: binaryData.fileSize || binaryData.fileSizeBytes || binaryData.dataSize || '',
    messageId,
    gmailId,
    dateEmail,
    fromAddress,
    subject,
  });
}

return {
  json: { messageId, gmailId, dateEmail, fromAddress, subject, bodyText, documentItems },
  binary,
};

const email = $input.item.json || {};
const binary = $input.item.binary || {};
const subject = String(email.subject || '');
const body = String(email.bodyText || '');
const documentItems = Array.isArray(email.documentItems) ? email.documentItems : [];
const attachmentNames = documentItems.map(a => a.fileName || '').join(' ');
const haystack = (subject + '\n' + body.slice(0, 3000) + '\n' + attachmentNames).toLowerCase();

const isQuoteLike = /\b(quote|quotation|estimate|proposal|tender)\b/i.test(haystack);
const isBankLike = /\b(bank statement|account summary|offset account|transaction summary|trust receipt|contribution|deposit|transfer|inflow)\b/i.test(haystack);
const isContributionLike = /\b(contribution|trust receipt|deposit|bond release|rental bond|tenant bond|incoming project funds|paid by payer)\b/i.test(haystack);
const isDedicatedBankStatement = /\b(bank statement|account summary|offset account|transaction summary)\b/i.test(haystack) && !isContributionLike;
const isUtilityLike = /\b(electricity|water|internet|insurance|council rates|utility|utilities)\b/i.test(haystack);
const isPaymentProofLike = /\b(receipt|paid|payment confirmation|remittance|amount due 0|balance due 0|deft|bpay|stripe|visa|mastercard)\b/i.test(haystack);

const content = [];
const shouldSendAttachments = isBankLike || isUtilityLike || isPaymentProofLike || !isQuoteLike;
const MAX_ATTACHMENT_BYTES = 6 * 1024 * 1024;
const MAX_TOTAL_BYTES = 14 * 1024 * 1024;
let totalBytes = 0;
const sentAttachments = [];
const skippedAttachments = [];

if (shouldSendAttachments) {
  for (const doc of documentItems) {
    const key = doc.key;
    const binaryData = key ? binary[key] : null;
    const mime = String(doc.mimeType || binaryData?.mimeType || '').trim();
    const fileName = String(doc.fileName || binaryData?.fileName || key || 'attachment').trim();
    if (!binaryData || (mime !== 'application/pdf' && !mime.startsWith('image/'))) continue;
    try {
      const buffer = await this.helpers.getBinaryDataBuffer(0, key);
      const size = buffer.length;
      if (size > MAX_ATTACHMENT_BYTES || totalBytes + size > MAX_TOTAL_BYTES) {
        skippedAttachments.push(fileName + ' (' + size + ' bytes)');
        continue;
      }
      totalBytes += size;
      const base64 = buffer.toString('base64');
      if (mime === 'application/pdf') {
        content.push({ type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: base64 } });
      } else {
        content.push({ type: 'image', source: { type: 'base64', media_type: mime, data: base64 } });
      }
      sentAttachments.push(fileName);
    } catch (e) {
      skippedAttachments.push(fileName + ' (read failed: ' + e.message + ')');
    }
  }
}

const system = [
'You extract structured records for a residential construction project tracker. Return ONLY valid JSON.',
'Project: the project site.',
'Target table rules:',
'- INVOICES: invoices, receipts, payment requests, payment confirmations, direct project costs.',
'- QUOTES: quotes, estimates, proposals, tenders.',
'- OPERATING_EXPENSES: utilities and recurring/holding costs.',
'- CONTRIBUTIONS: incoming money to the project from PAYER_C, PAYER_B, PAYER_A, or Tenants; trust receipts; deposit receipts; offset/bank statements showing incoming project funds.',
'- TIMELINE_ONLY: project events/admin with no direct financial transaction.',
'Contribution rules:',
'IMPORTANT COMPACT MODE FOR BACKFILL: output must be short and valid JSON. Do not enumerate bank statement transactions in this workflow.',
'- Contributions are incoming credits only.',
'- Contributors must be PAYER_A, PAYER_B, PAYER_C, Tenants, or Unknown.',
'- Trust receipts, purchaser deposit receipts, offset summaries, and bank statements with incoming project funds should use target_table=CONTRIBUTIONS.',
'- Populate contributions[] for every clear contribution/inflow found. If there are many rows, include only clear project contributions and set need_review=true with a short reason.',
'- Keep bank_transactions as [] in this backfill workflow. Bank statement reconciliation is handled separately; do not list transaction rows here.',
'- Exclude personal/non-project transactions, tax office personal activity, internal transfers and offset migrations from contributions.',
'- For trust receipts, deposit receipts, bond release receipts and emails saying someone paid/received funds, extract contribution rows only; do not describe every PDF line.',
'Paid evidence: use receipts/payment confirmations/explicit paid emails as evidence; if uncertain set need_review=true.',
'Need review: true if amount, payer, relationship or classification is unclear.',
'Document rule: do not invent Drive links; workflow uploads separately.',
'Return this exact JSON shape:',
'{',
'  "target_table":"INVOICES|QUOTES|OPERATING_EXPENSES|CONTRIBUTIONS|TIMELINE_ONLY|UNKNOWN",',
'  "record":{"date":"YYYY-MM-DD or null","vendor":"string or null","document_type":"INVOICE|QUOTE|RECEIPT|BANK_STATEMENT|REGULATORY|UTILITY_BILL|PAYMENT_CONFIRMATION|UNKNOWN","invoice_number":"string or null","amount_ex_gst":null,"gst":null,"amount_inc_gst":null,"status":"string","due_date":null,"paid_date":null,"expiry_date":null,"decision":null,"accepted_date":null,"accepted_by":null,"payer_member":"PAYER_A|PAYER_B|PAYER_C|Tenants|Unknown|null","budget_impact":"PROJECT_EXPENSE|OPERATING_EXPENSE|CONTRIBUTION|PERSONAL_EXCLUDED|INTERNAL_TRANSFER|REIMBURSEMENT|INFO_ONLY","category":"string or null","phase_of_project":"Planning & Approval|Survey & Site Investigation|Design & Engineering|Certification & Compliance|Demolition & Site Prep|Construction|Operating / Holding Costs|Excluded / Personal","description":"one sentence","notes":"string","need_review":false,"need_review_reason":"string","receipt_received":"Yes|No|Need review|Yes - confirm document","paid_evidence":false,"paid_evidence_source":"RECEIPT|PAYMENT_CONFIRMATION|EXPLICIT_EMAIL|BANK_STATEMENT|MANUAL|UNKNOWN","paid_evidence_detail":"short human explanation","urgency":"NONE|SOON|OVERDUE|REVIEW"},',
'  "contributions":[{"date":"YYYY-MM-DD","contributor":"PAYER_A|PAYER_B|PAYER_C|Tenants|Unknown","amount":0,"description":"raw description"}],',
'  "bank_transactions":[{"date":"YYYY-MM-DD","direction":"INFLOW|OUTFLOW","description":"raw bank description","amount":0,"balance":null,"project_relevance":"PROJECT|OPERATING|CONTRIBUTION|TENANT|PERSONAL|INTERNAL_TRANSFER|UNKNOWN","transaction_category":"string","payer_payee":"string","contributor":"PAYER_A|PAYER_B|PAYER_C|Tenants|Unknown|null","matched_payment_id":"string|null","match_status":"MATCHED|POSSIBLE_MATCH|UNMATCHED|CONFLICT|EXCLUDED","need_review":false,"notes":"string"}],',
'  "timeline":{"event_type":"string","description":"one sentence"}',
'}'
].join('\n');

content.push({type:'text', text:
  'message_id: ' + email.messageId + '\n' +
  'from: ' + email.fromAddress + '\n' +
  'subject: ' + email.subject + '\n' +
  'date: ' + email.dateEmail + '\n' +
  'bank_or_contribution_like: ' + isBankLike + '\n' +
  'contribution_compact_mode: ' + isContributionLike + '\n' +
  'attachments_available: ' + documentItems.length + '\n' +
  'attachments_sent_to_claude: ' + sentAttachments.join('; ') + '\n' +
  'attachments_skipped_for_claude: ' + skippedAttachments.join('; ') + '\n' +
  'attachment_names: ' + attachmentNames + '\n\n---EMAIL BODY---\n' + body
});

return {
  model: 'claude-sonnet-4-5',
  max_tokens: isBankLike ? 3600 : (isQuoteLike ? 1400 : 2400),
  system,
  messages: [{ role: 'user', content }]
};

const original = $('Extract Email Context').item.json;
const PHASES = [
  'Planning & Approval',
  'Survey & Site Investigation',
  'Design & Engineering',
  'Certification & Compliance',
  'Demolition & Site Prep',
  'Construction',
  'Operating / Holding Costs',
  'Excluded / Personal',
];

let claudeStopReason = '';
let parseFailed = false;

let parsed = {
  target_table: 'UNKNOWN',
  record: {
    date: null,
    vendor: null,
    document_type: 'UNKNOWN',
    invoice_number: null,
    amount_ex_gst: null,
    gst: null,
    amount_inc_gst: null,
    status: 'UNKNOWN',
    due_date: null,
    paid_date: null,
    expiry_date: null,
    decision: null,
    accepted_date: null,
    accepted_by: null,
    payer_member: null,
    budget_impact: 'INFO_ONLY',
    category: null,
    phase_of_project: null,
    description: 'Email could not be parsed.',
    notes: '',
    need_review: true,
    need_review_reason: 'Email could not be parsed.',
    receipt_received: 'Need review',
    paid_evidence: false,
    paid_evidence_source: 'UNKNOWN',
    paid_evidence_detail: '',
    urgency: 'REVIEW',
  },
  contributions: [],
  bank_transactions: [],
  timeline: { event_type: 'UNKNOWN', description: 'Email could not be parsed.' },
};

try {
  const response = $input.item.json;
  claudeStopReason = String(response.stop_reason || '');
  const text = response.content?.[0]?.text || response.content?.[0]?.text?.value || '';
  const fence = String.fromCharCode(96, 96, 96);
  const fencedMatch = text.match(new RegExp(fence + '(?:json)?\\s*([\\s\\S]*?)' + fence));
  let jsonText = (fencedMatch ? fencedMatch[1] : text).trim();
  jsonText = jsonText.replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
  const firstBrace = jsonText.indexOf('{');
  const lastBrace = jsonText.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) jsonText = jsonText.slice(firstBrace, lastBrace + 1);
  const candidate = JSON.parse(jsonText);
  parsed = {
    ...parsed,
    ...candidate,
    record: { ...parsed.record, ...(candidate.record || {}) },
    contributions: Array.isArray(candidate.contributions) ? candidate.contributions : [],
    bank_transactions: Array.isArray(candidate.bank_transactions) ? candidate.bank_transactions : [],
    timeline: { ...parsed.timeline, ...(candidate.timeline || {}) },
  };
} catch (e) {
  parseFailed = true;
  parsed.record.notes = 'Claude parse error: ' + e.message;
  parsed.record.need_review_reason = parsed.record.notes;
}

if (claudeStopReason === 'max_tokens') {
  parseFailed = true;
  parsed.record.need_review = true;
  parsed.record.need_review_reason = 'Claude output was truncated at max_tokens. Re-run with compact extraction or manual review.';
  parsed.record.notes = (parsed.record.notes ? parsed.record.notes + ' | ' : '') + parsed.record.need_review_reason;
}

const r = parsed.record || {};

function cleanAmount(value) {
  if (value === null || value === undefined || value === '') return '';
  const number = Number(String(value).replace(/[^0-9.-]/g, ''));
  return Number.isFinite(number) ? number.toFixed(2) : '';
}

function slug(value) {
  return String(value || '').toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '').slice(0, 80);
}

function bool(value) {
  return value === true || ['true', 'yes', 'y', '1', 'review'].includes(String(value).toLowerCase());
}

function normalizeTargetTable(value) {
  const table = String(value || '').trim().toUpperCase();
  const allowed = ['INVOICES', 'QUOTES', 'OPERATING_EXPENSES', 'CONTRIBUTIONS', 'TIMELINE_ONLY', 'UNKNOWN'];
  return allowed.includes(table) ? table : 'UNKNOWN';
}

function normalizeStatus(value, targetTable, paidEvidence) {
  let status = String(value || '').trim().toUpperCase();
  if (paidEvidence && ['UNKNOWN', 'PENDING', ''].includes(status) && targetTable !== 'QUOTES') status = 'PAID';
  const invoiceAllowed = ['PENDING', 'PAID', 'PARTIALLY_PAID', 'DEPOSIT_PAID', 'AUTO_PAID', 'EXCLUDED', 'UNKNOWN'];
  const quoteAllowed = ['RECEIVED', 'UNDER_REVIEW', 'ACCEPTED', 'REJECTED', 'EXPIRED', 'SUPERSEDED', 'TO_REVIEW', 'UNKNOWN'];
  const allowed = targetTable === 'QUOTES' ? quoteAllowed : invoiceAllowed;
  return allowed.includes(status) ? status : (targetTable === 'QUOTES' ? 'RECEIVED' : 'UNKNOWN');
}

function normalizePayer(value) {
  const raw = String(value || '').trim().toLowerCase();
  if (!raw) return '';
  if (raw.includes('payer_a') || raw === 'me') return 'PAYER_A';
  if (raw.includes('payer_b')) return 'PAYER_B';
  if (raw.includes('payer_c')) return 'PAYER_C';
  if (raw.includes('tenant')) return 'Tenants';
  if (['unknown', 'unclear'].includes(raw)) return 'Unknown';
  return value;
}

function normalizeEvidenceSource(value, paidEvidence, docType) {
  const raw = String(value || '').trim().toUpperCase();
  const allowed = ['RECEIPT', 'PAYMENT_CONFIRMATION', 'EXPLICIT_EMAIL', 'BANK_STATEMENT', 'MANUAL', 'UNKNOWN'];
  if (allowed.includes(raw)) return raw;
  if (!paidEvidence) return 'UNKNOWN';
  const dt = String(docType || '').toUpperCase();
  if (dt === 'RECEIPT') return 'RECEIPT';
  if (dt === 'PAYMENT_CONFIRMATION') return 'PAYMENT_CONFIRMATION';
  if (dt === 'BANK_STATEMENT') return 'BANK_STATEMENT';
  return 'EXPLICIT_EMAIL';
}

function phaseFromText(targetTable, fields) {
  const text = fields.map(v => String(v || '')).join(' ').toLowerCase();
  if (/ato|tax office|personal tax|personal/.test(text)) return 'Excluded / Personal';
  if (targetTable === 'OPERATING_EXPENSES' || /electricity|water|internet|utility|utilities|insurance|council rates|holding/.test(text)) return 'Operating / Holding Costs';
  if (/demolition|demo only|sediment|site prep/.test(text)) return 'Demolition & Site Prep';
  if (/certif|construction certificate|occupation certificate|\bcc\b|\boc\b|inspection|long service levy|compliance condition|certex/.test(text)) return 'Certification & Compliance';
  if (/engineering|structural|civil|stormwater|flood|basix|thermal|vanguard|hills consulting/.test(text)) return 'Design & Engineering';
  if (/survey|boundary|pegout|setout|cctv|pipe locat|underground|civilscan|3linx/.test(text)) return 'Survey & Site Investigation';
  if (/planning|approval|\bda\b|s4\.55|council application|polaris|development application|town planning/.test(text)) return 'Planning & Approval';
  if (/plumbing|electrical|concrete|formwork|windows|glazing|construction|builder|trade|tender/.test(text)) return 'Construction';
  return targetTable === 'QUOTES' ? 'Construction' : 'Planning & Approval';
}

let targetTable = normalizeTargetTable(parsed.target_table);
const hasContributionRows = Array.isArray(parsed.contributions) && parsed.contributions.some(c => cleanAmount(c.amount));
const hasContributionBankInflows = Array.isArray(parsed.bank_transactions) && parsed.bank_transactions.some(tx => {
  const direction = String(tx.direction || '').toUpperCase();
  const relevance = String(tx.project_relevance || '').toUpperCase();
  return direction === 'INFLOW' && ['CONTRIBUTION', 'TENANT'].includes(relevance) && cleanAmount(tx.amount);
});
const looksContributionRecord = ['BANK_STATEMENT', 'PAYMENT_CONFIRMATION', 'RECEIPT'].includes(String(r.document_type || '').toUpperCase()) && String(r.budget_impact || '').toUpperCase() === 'CONTRIBUTION' && cleanAmount(r.amount_inc_gst || r.amount_aud || r.amount_ex_gst);
if (hasContributionRows || hasContributionBankInflows || looksContributionRecord) {
  targetTable = 'CONTRIBUTIONS';
}
const date = r.date || original.dateEmail || '';
const vendor = r.vendor || '';
const invoiceNumber = r.invoice_number || '';
const amountInc = cleanAmount(r.amount_inc_gst || r.amount_ex_gst || r.amount_aud);
const paidEvidence = bool(r.paid_evidence);
const status = normalizeStatus(r.status, targetTable, paidEvidence);
const needReview = bool(r.need_review || r.to_review);
const phase = PHASES.includes(r.phase_of_project) ? r.phase_of_project : phaseFromText(targetTable, [r.category, r.description, r.notes, vendor, original.subject]);
const paidEvidenceSource = normalizeEvidenceSource(r.paid_evidence_source, paidEvidence, r.document_type);
const paidEvidenceDetail = r.paid_evidence_detail || (paidEvidence ? `Payment evidence from ${paidEvidenceSource}.` : '');

const messageSlug = slug(String(original.messageId || '').replace(/[<>]/g, '').trim());
const amountKey = amountInc || cleanAmount(r.amount_aud || r.amount_ex_gst) || '';
const invoiceKey = slug(invoiceNumber);

function isUtilityBundle() {
  const text = [vendor, r.category, r.description, r.notes, original.subject]
    .map(v => String(v || '').toLowerCase())
    .join(' ');
  return /multiple|bundle|utility|utilities|electricity|water|internet/.test(text) && amountKey;
}

let recordId;

if (targetTable === 'INVOICES' && vendor && invoiceNumber) {
  recordId = ['INVOICES', slug(vendor), invoiceKey].join('__');
} else if (targetTable === 'QUOTES' && invoiceNumber) {
  recordId = ['QUOTES', invoiceKey].join('__');
} else if (targetTable === 'OPERATING_EXPENSES' && vendor && invoiceNumber) {
  recordId = ['OPERATING_EXPENSES', slug(vendor), invoiceKey].join('__');
} else if (targetTable === 'OPERATING_EXPENSES' && isUtilityBundle()) {
  recordId = ['OPERATING_EXPENSES', date, 'utilities_bundle', messageSlug, amountKey].join('__');
} else if (['INVOICES', 'OPERATING_EXPENSES', 'QUOTES'].includes(targetTable)) {
  recordId = [targetTable, date, messageSlug, amountKey].join('__');
} else {
  recordId = [targetTable, date, messageSlug].join('__');
}

const gmailAccount = 'project-mailbox@example.com';
const cleanMessageId = String(original.messageId || '').replace(/[<>]/g, '').trim();
const gmailLink = cleanMessageId
  ? `https://mail.google.com/mail/u/${gmailAccount}/#search/rfc822msgid%3A${encodeURIComponent(cleanMessageId)}`
  : (original.gmailId ? `https://mail.google.com/mail/u/${gmailAccount}/#search/${encodeURIComponent(original.gmailId)}` : '');
const receiptReceived = r.receipt_received || (paidEvidence ? 'Yes' : (['PAID', 'AUTO_PAID', 'DEPOSIT_PAID'].includes(status) ? 'Yes - confirm document' : 'No'));

return {
  __claude_output_usable: !(parseFailed || claudeStopReason === 'max_tokens'),
  __claude_parse_failed: parseFailed,
  claude_stop_reason: claudeStopReason,
  ...parsed,
  ...r,
  target_table: targetTable,
  record_id: recordId,
  quote_id: targetTable === 'QUOTES' ? recordId : '',
  date,
  vendor,
  document_type: r.document_type || 'UNKNOWN',
  invoice_number: invoiceNumber,
  quote_number: targetTable === 'QUOTES' ? invoiceNumber : '',
  amount_ex_gst: cleanAmount(r.amount_ex_gst),
  gst: cleanAmount(r.gst),
  amount_inc_gst: cleanAmount(r.amount_inc_gst || r.amount_ex_gst || r.amount_aud),
  status,
  due_date: r.due_date || '',
  paid_date: r.paid_date || '',
  expiry_date: r.expiry_date || '',
  decision: r.decision || (targetTable === 'QUOTES' ? status : ''),
  accepted_date: r.accepted_date || '',
  accepted_by: normalizePayer(r.accepted_by),
  payer_member: normalizePayer(r.payer_member),
  budget_impact: r.budget_impact || (targetTable === 'QUOTES' ? 'INFO_ONLY' : 'INFO_ONLY'),
  category: r.category || '',
  phase_of_project: phase,
  description: r.description || parsed.timeline?.description || 'No description extracted.',
  notes: r.notes || parsed.record.notes || '',
  need_review: needReview,
  need_review_label: needReview ? 'Yes' : 'No',
  need_review_reason: r.need_review_reason || (needReview ? 'Needs human review.' : ''),
  receipt_received: receiptReceived,
  paid_evidence: paidEvidence,
  paid_evidence_source: paidEvidenceSource,
  paid_evidence_detail: paidEvidenceDetail,
  bank_match_status: r.bank_match_status || 'NOT_CHECKED',
  matched_bank_transaction_id: r.matched_bank_transaction_id || '',
  urgency: r.urgency || (needReview ? 'REVIEW' : 'NONE'),
  message_id: original.messageId,
  gmail_id: original.gmailId,
  gmail_link: gmailLink,
  source_file_name: (original.attachments || []).map(a => a.name).join('; '),
  email_subject: original.subject || '',
  email_from: original.fromAddress || '',
  created_at: new Date().toISOString(),
  updated_at: new Date().toISOString(),
};

const seen = new Set();
const output = [];

function normContributor(value) {
  const raw = String(value || '').trim().toLowerCase();
  if (raw.includes('payer_a') || raw === 'me') return 'PAYER_A';
  if (raw.includes('payer_b')) return 'PAYER_B';
  if (raw.includes('payer_c')) return 'PAYER_C';
  if (raw.includes('tenant')) return 'Tenants';
  return 'Unknown';
}
function amountNumber(value) {
  const n = Number(String(value || '').replace(/[^0-9.-]/g, ''));
  return Number.isFinite(n) ? Math.abs(n) : 0;
}
function cleanText(value) { return String(value || '').replace(/\s+/g, ' ').trim(); }
function safeIdPart(value) { return cleanText(value).toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '').slice(0, 80); }

function addCandidate(data, c) {
  const amount = amountNumber(c.amount);
  if (!amount) return;
  const contributor = normContributor(c.contributor);
  const date = c.date || data.date || '';
  const description = cleanText(c.description || data.description || 'Contribution');
  const sourceRecordId = data.record_id || ['CONTRIBUTIONS', data.date || '', safeIdPart(data.message_id || data.gmail_id || data.email_subject || 'source')].join('__');
  const id = [date, contributor, amount.toFixed(2), safeIdPart(description).slice(0, 48)].join('__');
  if (seen.has(id)) return;
  seen.add(id);
  output.push({ json: {
    __has_contribution_row: true,
    Transaction_ID: id,
    Date: date,
    Contributor: contributor,
    Amount: amount.toFixed(2),
    Source: c.source || 'EMAIL_OR_STATEMENT',
    Description: description,
    Period_Start: '',
    Period_End: '',
    Need_Review: data.need_review_label || (contributor === 'Unknown' ? 'Yes' : 'No'),
    Statement_Link: '',
    Gmail_Link: data.gmail_link || '',
    Notes: data.notes || '',
    Related_Record_ID: sourceRecordId,
    Drive_Link: '',
    Updated_At: data.updated_at || new Date().toISOString(),
  }});
}

for (const inputItem of $input.all()) {
  const data = inputItem.json || {};
  let candidateCount = 0;
  for (const c of Array.isArray(data.contributions) ? data.contributions : []) {
    candidateCount++;
    addCandidate(data, { date: c.date || data.date, contributor: c.contributor, amount: c.amount, description: c.description || data.description, source: 'CONTRIBUTION_EXTRACTION' });
  }
