function gmailLink(messageId, gmailId) {
  const cleanMessageId = String(messageId || '').replace(/[<>]/g, '').trim();
  if (cleanMessageId) {
    return 'https://mail.google.com/mail/u/project-mailbox@example.com/#search/rfc822msgid%3A' + encodeURIComponent(cleanMessageId);
  }
  return gmailId ? ('https://mail.google.com/mail/u/project-mailbox@example.com/#search/' + encodeURIComponent(gmailId)) : '';
}

function safePart(value, fallback) {
  const cleaned = String(value || fallback || 'document')
    .replace(/[\\/:*?"<>|]/g, '_')
    .replace(/\s+/g, ' ')
    .trim();
  return (cleaned || fallback || 'document').slice(0, 140);
}

function extensionFromMime(mime) {
  if (mime === 'application/pdf') return '.pdf';
  if (mime === 'image/png') return '.png';
  if (mime === 'image/jpeg' || mime === 'image/jpg') return '.jpg';
  if (mime === 'image/heic') return '.heic';
  if (mime === 'image/webp') return '.webp';
  return '';
}

function parseSize(value) {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  const text = String(value || '').trim().toLowerCase();
  if (!text) return 0;
  const match = text.match(/([\d.]+)\s*(b|kb|mb|gb)?/i);
  if (!match) return 0;
  const n = Number(match[1]);
  if (!Number.isFinite(n)) return 0;
  const unit = match[2] || 'b';
  if (unit === 'gb') return n * 1024 * 1024 * 1024;
  if (unit === 'mb') return n * 1024 * 1024;
  if (unit === 'kb') return n * 1024;
  return n;
}

