  const allowed = mime === 'application/pdf' || mime.startsWith('image/');
  const estimatedSize = parseSize(doc.fileSize || binaryData?.fileSize || binaryData?.fileSizeBytes || binaryData?.dataSize || 0);
  const tooLarge = estimatedSize > MAX_UPLOAD_BYTES;
  if (!related || !binaryData || !allowed || tooLarge) continue;

  const ext = extensionFromMime(mime);
  let fileName = safePart(doc.fileName || binaryData.fileName, 'attachment_' + (i + 1) + ext);
  if (ext && !fileName.toLowerCase().endsWith(ext)) fileName += ext;
  const driveName = safePart(date + '_' + fileName, date + '_' + related + '_' + (i + 1) + (ext || '.bin'));
  const documentId = safePart(related + '__' + fileName, related + '__document_' + (i + 1));

  items.push({
