function normDirection(value, amount) {
  const raw = String(value || '').trim().toUpperCase();
  if (raw === 'INFLOW' || raw === 'OUTFLOW') return raw;
  const n = Number(String(amount || '').replace(/[^0-9.-]/g, ''));
  return n < 0 ? 'OUTFLOW' : 'INFLOW';
}

function normContributor(value) {
  const raw = String(value || '').trim().toLowerCase();
  if (!raw || raw === 'null') return '';
  if (raw.includes('payer_a') || raw === 'me') return 'PAYER_A';
  if (raw.includes('payer_b')) return 'PAYER_B';
  if (raw.includes('payer_c')) return 'PAYER_C';
  if (raw.includes('tenant') || raw.includes('rent')) return 'Tenants';
  return 'Unknown';
}

function slug(value) {
  return String(value || '').toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '').slice(0, 70);
}

function stableTransactionKey(description, matchedPaymentId) {
  const text = String([description, matchedPaymentId].filter(Boolean).join(' '));
  const digitRuns = [...text.matchAll(/\d[\d\s-]{7,}\d/g)]
    .map(m => m[0].replace(/\D/g, ''))
    .filter(v => v.length >= 8)
    .sort((a, b) => b.length - a.length);
  if (digitRuns.length) return 'ref_' + digitRuns[0].slice(0, 32);
  return slug(description);
}

return transactions.map(t => {
  const amount = Number(String(t.amount || '').replace(/[^0-9.-]/g, ''));
